package com.franco.desco.application.sanitation.service;import com.franco.desco.application.sanitation.*;import com.franco.desco.application.sanitation.port.in.SanitationUseCase;import com.franco.desco.application.sanitation.port.out.SanitationPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.sanitation.SanitationModels;
public final class SanitationApplicationService implements SanitationUseCase{private final SanitationPersistencePort p;public SanitationApplicationService(SanitationPersistencePort p){this.p=p;}public AppResult<PageResult<SanitationModels.Summary>>list(SanitationCommands.ListCases c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.list(c,i,m),"SANIDAD_LISTADA","SANIDAD_NO_LISTADA",AppStatus.BAD_REQUEST);}public AppResult<SanitationModels.Detail>get(SanitationCommands.Get c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.get(c,i,m),"CASO_CONSULTADO","CASO_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<Long>create(SanitationCommands.Create c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.create(c,i,m),"CASO_REGISTRADO","CASO_NO_REGISTRADO");}public AppResult<Void>update(SanitationCommands.Update c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.update(c,i,m),"CASO_ACTUALIZADO","CASO_NO_ACTUALIZADO",AppStatus.BAD_REQUEST);}public AppResult<Void>changeState(SanitationCommands.ChangeState c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.changeState(c,i,m),"ESTADO_SANITARIO_ACTUALIZADO","ESTADO_SANITARIO_NO_ACTUALIZADO",AppStatus.BAD_REQUEST);}public AppResult<Void>close(SanitationCommands.Close c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.close(c,i,m),"CASO_CERRADO","CASO_NO_CERRADO",AppStatus.BAD_REQUEST);}public AppResult<Long>addTreatment(SanitationCommands.Treatment c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.addTreatment(c,i,m),"TRATAMIENTO_REGISTRADO","TRATAMIENTO_NO_REGISTRADO");}public AppResult<Long>addFollowUp(SanitationCommands.FollowUp c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.addFollowUp(c,i,m),"SEGUIMIENTO_REGISTRADO","SEGUIMIENTO_NO_REGISTRADO");}}
